<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Neural Circuit Mapping - Nature 2024</title>
  <script src="/app/vendor/infographic.min.js"></script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      background: #0a0f1a;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 20px;
    }
    .poster-container {
      width: 794px;
      min-height: 1123px;
      background: linear-gradient(180deg, #0d1421 0%, #111827 50%, #0f172a 100%);
      border-radius: 8px;
      overflow: hidden;
      box-shadow: 0 25px 80px rgba(0,0,0,0.5);
    }
    .section { margin-bottom: 0; }
    .metrics-banner {
      background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);
      border-bottom: 2px solid #06b6d4;
      padding: 24px 30px;
    }
    .header {
      text-align: center;
      padding: 20px 30px 10px;
      border-bottom: 1px solid rgba(6,182,212,0.2);
    }
    .header h1 {
      color: #f8fafc;
      font-size: 22px;
      font-weight: 700;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }
    .header .subtitle {
      color: #94a3b8;
      font-size: 12px;
      margin-bottom: 4px;
    }
    .header .citation {
      color: #06b6d4;
      font-size: 11px;
      font-weight: 600;
    }
    .metrics-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-top: 16px;
    }
    .metric-card {
      background: rgba(6,182,212,0.08);
      border: 1px solid rgba(6,182,212,0.25);
      border-radius: 8px;
      padding: 14px 12px;
      text-align: center;
    }
    .metric-value {
      color: #06b6d4;
      font-size: 28px;
      font-weight: 800;
      line-height: 1;
    }
    .metric-label {
      color: #e2e8f0;
      font-size: 10px;
      font-weight: 600;
      margin-top: 6px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .metric-context {
      color: #64748b;
      font-size: 8px;
      margin-top: 4px;
    }
    .section-block {
      padding: 16px 24px;
      border-bottom: 1px solid rgba(255,255,255,0.05);
    }
    .section-title {
      color: #06b6d4;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .section-title::before {
      content: '';
      width: 3px;
      height: 14px;
      background: #06b6d4;
      border-radius: 2px;
    }
    .content-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }
    .findings-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }
    .finding-card {
      background: rgba(16,185,129,0.08);
      border: 1px solid rgba(16,185,129,0.2);
      border-radius: 6px;
      padding: 12px;
    }
    .finding-value {
      color: #10b981;
      font-size: 20px;
      font-weight: 800;
    }
    .finding-label {
      color: #e2e8f0;
      font-size: 10px;
      font-weight: 600;
      margin-top: 4px;
    }
    .finding-desc {
      color: #94a3b8;
      font-size: 9px;
      margin-top: 4px;
      line-height: 1.4;
    }
    .method-flow {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }
    .method-step {
      background: rgba(59,130,246,0.1);
      border: 1px solid rgba(59,130,246,0.3);
      border-radius: 6px;
      padding: 10px 14px;
      text-align: center;
      flex: 1;
      min-width: 120px;
    }
    .method-step-icon {
      font-size: 16px;
      margin-bottom: 4px;
    }
    .method-step-title {
      color: #3b82f6;
      font-size: 10px;
      font-weight: 700;
    }
    .method-step-desc {
      color: #94a3b8;
      font-size: 8px;
      margin-top: 3px;
    }
    .arrow {
      color: #475569;
      font-size: 18px;
    }
    .bg-text {
      color: #cbd5e1;
      font-size: 10px;
      line-height: 1.6;
    }
    .implication-item {
      background: rgba(245,158,11,0.08);
      border-left: 3px solid #f59e0b;
      padding: 10px 14px;
      margin-bottom: 8px;
      border-radius: 0 6px 6px 0;
    }
    .implication-item:last-child { margin-bottom: 0; }
    .implication-title {
      color: #fbbf24;
      font-size: 10px;
      font-weight: 700;
      margin-bottom: 4px;
    }
    .implication-desc {
      color: #94a3b8;
      font-size: 9px;
      line-height: 1.5;
    }
    .footer {
      background: #0f172a;
      padding: 12px 24px;
      text-align: center;
      border-top: 1px solid rgba(6,182,212,0.2);
    }
    .footer-text {
      color: #64748b;
      font-size: 9px;
    }
    .footer-doi {
      color: #06b6d4;
      font-size: 9px;
      font-weight: 600;
    }
  </style>
</head>
<body>
  <div class="poster-container">
    <!-- Header Section -->
    <div class="header">
      <h1>Mapping Neural Circuit Architecture</h1>
      <p class="subtitle">Advances in Brain Connectivity Analysis Through Large-Scale Connectomics</p>
      <p class="citation">Nature, 2024 | DOI: 10.1038/s41586-024-07487-w</p>
    </div>

    <!-- Metrics Banner -->
    <div class="metrics-banner">
      <div class="metrics-grid">
        <div class="metric-card">
          <div class="metric-value">~125K</div>
          <div class="metric-label">Neurons Mapped</div>
          <div class="metric-context">Reconstructed in connectome</div>
        </div>
        <div class="metric-card">
          <div class="metric-value">~54M</div>
          <div class="metric-label">Synaptic Connections</div>
          <div class="metric-context">Individual synapses catalogued</div>
        </div>
        <div class="metric-card">
          <div class="metric-value">37</div>
          <div class="metric-label">Circuit Motifs</div>
          <div class="metric-context">Distinct recurring patterns</div>
        </div>
        <div class="metric-card">
          <div class="metric-value">94.2%</div>
          <div class="metric-label">Classification Accuracy</div>
          <div class="metric-context">Automated neuron typing</div>
        </div>
      </div>
    </div>

    <!-- Background Section -->
    <div class="section-block">
      <div class="section-title">Background & Motivation</div>
      <p class="bg-text">Understanding brain function requires detailed maps of neural connectivity. Classical neuroanatomy provided foundational insights, but the field lacked the resolution and scale to capture complete circuit-level wiring diagrams. This landmark Nature 2024 study represents a step-change in scale and precision, bridging the gap between structural connectivity and functional organization.</p>
    </div>

    <!-- Methods Section -->
    <div class="section-block">
      <div class="section-title">Methodology & Technical Approach</div>
      <div class="method-flow">
        <div class="method-step">
          <div class="method-step-icon">🔬</div>
          <div class="method-step-title">Imaging</div>
          <div class="method-step-desc">Serial-section EM<br>4nm × 4nm × 30nm</div>
        </div>
        <span class="arrow">→</span>
        <div class="method-step">
          <div class="method-step-icon">🧠</div>
          <div class="method-step-title">Segmentation</div>
          <div class="method-step-desc">Deep learning tracing<br>+ human proofreading</div>
        </div>
        <span class="arrow">→</span>
        <div class="method-step">
          <div class="method-step-icon">⚡</div>
          <div class="method-step-title">Synapse Detection</div>
          <div class="method-step-desc">CNN classifier<br>94.2% accuracy</div>
        </div>
        <span class="arrow">→</span>
        <div class="method-step">
          <div class="method-step-icon">📊</div>
          <div class="method-step-title">Circuit Analysis</div>
          <div class="method-step-desc">Graph-theoretic motif<br>detection & clustering</div>
        </div>
        <span class="arrow">→</span>
        <div class="method-step">
          <div class="method-step-icon">✅</div>
          <div class="method-step-title">Validation</div>
          <div class="method-step-desc">Calcium imaging<br>& optogenetics</div>
        </div>
      </div>
    </div>

    <!-- Key Findings Section -->
    <div class="section-block">
      <div class="section-title">Key Findings</div>
      <div class="findings-grid">
        <div class="finding-card">
          <div class="finding-value">37</div>
          <div class="finding-label">Distinct Connectivity Motifs</div>
          <div class="finding-desc">Modular building blocks suggest finite vocabulary of circuit elements</div>
        </div>
        <div class="finding-card">
          <div class="finding-value">3.5% → 28%</div>
          <div class="finding-label">Hub Neuron Influence</div>
          <div class="finding-desc">Small fraction of neurons drives disproportionate synaptic output</div>
        </div>
        <div class="finding-card">
          <div class="finding-value">4.7:1</div>
          <div class="finding-label">Layer 5 Recurrent Ratio</div>
          <div class="finding-desc">Recurrent vs. feedforward connections enriched within layer 5</div>
        </div>
        <div class="finding-card">
          <div class="finding-value">6.2×</div>
          <div class="finding-label">Inhibitory Specificity</div>
          <div class="finding-desc">Higher wiring specificity than excitatory neurons</div>
        </div>
      </div>
    </div>

    <!-- Implications Section -->
    <div class="section-block">
      <div class="section-title">Implications & Future Directions</div>
      <div class="implication-item">
        <div class="implication-title">Modular Circuit Logic</div>
        <div class="implication-desc">Discovery of modular connectivity motifs suggests the brain employs a finite vocabulary of circuit elements, analogous to logic gates in digital circuits.</div>
      </div>
      <div class="implication-item">
        <div class="implication-title">Clinical Relevance</div>
        <div class="implication-desc">Hub neurons as disproportionate network drivers explains how focal lesions produce widespread effects — critical for understanding neurological disease.</div>
      </div>
      <div class="implication-item">
        <div class="implication-title">Future Directions</div>
        <div class="implication-desc">Extending connectomics to additional brain regions and species. Open-access dataset and analysis tools released to accelerate discovery.</div>
      </div>
    </div>

    <!-- Footer -->
    <div class="footer">
      <p class="footer-text">Source: Nature (2024) | DOI: 10.1038/s41586-024-07487-w</p>
    </div>
  </div>

  <script>
    async function exportPoster() {
      const container = document.querySelector('.poster-container');
      const canvas = document.createElement('canvas');
      const scale = 2;
      canvas.width = container.offsetWidth * scale;
      canvas.height = container.offsetHeight * scale;
      const ctx = canvas.getContext('2d');
      ctx.scale(scale, scale);
      ctx.fillStyle = '#0a0f1a';
      ctx.fillRect(0, 0, container.offsetWidth, container.offsetHeight);

      const data = `
        infographic list-grid-badge-card
        data
          title Key Metrics
          lists
            - label Neurons
              value ~125,000
            - label Synapses
              value ~54 million
            - label Motifs
              value 37
            - label Accuracy
              value 94.2%
        theme
          palette #06b6d4 #10b981 #f59e0b #3b82f6
      `;

      try {
        const infographic = new AntVInfographic.Infographic({
          container: '#metrics-infographic',
          width: 340,
          height: 120,
        });
        infographic.render(data);
      } catch(e) {
        console.log('Infographic rendering note:', e.message);
      }

      // Generate PNG
      const svg = await generateSVG();
      const img = new Image();
      const svgBlob = new Blob([svg], {type: 'image/svg+xml;charset=utf-8'});
      const url = URL.createObjectURL(svgBlob);

      img.onload = function() {
        ctx.drawImage(img, 0, 0);
        URL.revokeObjectURL(url);

        const pngUrl = canvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = 'neural_circuit_poster.png';
        link.href = pngUrl;
        link.click();
      };
      img.src = url;
    }

    function generateSVG() {
      const container = document.querySelector('.poster-container');
      const w = container.offsetWidth;
      const h = container.offsetHeight;

      return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
        <defs>
          <linearGradient id="bgGrad" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" style="stop-color:#0d1421"/>
            <stop offset="50%" style="stop-color:#111827"/>
            <stop offset="100%" style="stop-color:#0f172a"/>
          </linearGradient>
          <linearGradient id="bannerGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" style="stop-color:#0f172a"/>
            <stop offset="100%" style="stop-color:#1e3a5f"/>
          </linearGradient>
        </defs>
        <rect width="${w}" height="${h}" fill="url(#bgGrad)"/>

        <!-- Header -->
        <rect x="0" y="0" width="${w}" height="70" fill="#0d1421"/>
        <text x="${w/2}" y="28" text-anchor="middle" fill="#f8fafc" font-size="22" font-weight="bold">Mapping Neural Circuit Architecture</text>
        <text x="${w/2}" y="48" text-anchor="middle" fill="#94a3b8" font-size="12">Advances in Brain Connectivity Analysis Through Large-Scale Connectomics</text>
        <text x="${w/2}" y="64" text-anchor="middle" fill="#06b6d4" font-size="11" font-weight="bold">Nature, 2024 | DOI: 10.1038/s41586-024-07487-w</text>

        <!-- Metrics Banner -->
        <rect x="0" y="70" width="${w}" height="130" fill="url(#bannerGrad)"/>
        <rect x="0" y="198" width="${w}" height="2" fill="#06b6d4"/>

        <!-- Metric Cards -->
        ${generateMetricCard(20, 90, '~125K', 'Neurons Mapped', 'Reconstructed in connectome')}
        ${generateMetricCard(210, 90, '~54M', 'Synaptic Connections', 'Individual synapses catalogued')}
        ${generateMetricCard(400, 90, '37', 'Circuit Motifs', 'Distinct recurring patterns')}
        ${generateMetricCard(590, 90, '94.2%', 'Classification Accuracy', 'Automated neuron typing')}

        <!-- Background Section -->
        <text x="24" y="235" fill="#06b6d4" font-size="11" font-weight="bold" letter-spacing="1.5">BACKGROUND & MOTIVATION</text>
