const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');

async function generatePoster() {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const page = await browser.newPage();

  // Set viewport to A0 portrait dimensions at 96 DPI
  // A0 = 841mm x 1189mm = 33.1in x 46.8in at 96 DPI = 3179 x 4494 pixels
  const width = 794;
  const height = 1123;

  await page.setViewport({
    width: width,
    height: height,
    deviceScaleFactor: 2
  });

  const htmlPath = path.join(__dirname, 'neural_circuit_poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 2000));

  // Generate PNG
  const pngBuffer = await page.screenshot({
    type: 'png',
    fullPage: true
  });

  const outputPath = path.join(__dirname, 'final_poster.png');
  fs.writeFileSync(outputPath, pngBuffer);

  console.log('Poster saved to:', outputPath);
  console.log('Size:', pngBuffer.length, 'bytes');

  await browser.close();
}

generatePoster().catch(console.error);

